1	'use client';
2	
3	import { AnimatePresence, motion } from 'framer-motion';
4	import { useEffect, useState } from 'react';
5	import styles from './hero.module.css';
6	
7	const PHRASES = ['Ownership Driven', 'Without Hiring', 'On Demand'] as const;
8	
9	export function Typewriter() {
10	  const [index, setIndex] = useState(0);
11	
12	  useEffect(() => {
13	    const interval = setInterval(() => {
14	      setIndex((prev) => (prev + 1) % PHRASES.length);
15	    }, 2400);
16	    return () => clearInterval(interval);
17	  }, []);
18	
19	  return (
20	    <span
21	      style={{
22	        display: 'inline-block',
23	        minWidth: '280px',
24	        textAlign: 'left',
25	        verticalAlign: 'baseline',
26	      }}
27	    >
28	      <AnimatePresence mode="wait">
29	        <motion.span
30	          key={index}
31	          className={styles['animate-span']}
32	          initial={{ opacity: 0, y: 10 }}
33	          animate={{ opacity: 1, y: 0 }}
34	          exit={{ opacity: 0, y: -10 }}
35	          transition={{ duration: 0.28, ease: 'easeInOut' }}
36	          style={{ display: 'inline-block' }}
37	        >
38	          {PHRASES[index]}
39	        </motion.span>
40	      </AnimatePresence>
41	    </span>
42	  );
43	}
